import assert from "node:assert/strict";
import { createServer } from "node:http";
import { readFile } from "node:fs/promises";
import { chromium } from "playwright";

// The document is generated by PortalURLTests using the real Swift/DataXML renderer.
const source = await readFile(new URL("../test/fixtures/mounted.html", import.meta.url), "utf8");
const runtime = await readFile(new URL("../dist/portal-runtime.js", import.meta.url), "utf8");
const requests: {url: string; enhanced: boolean}[] = [];
const server = createServer((request, response) => {
  const url = request.url ?? "/";
  requests.push({url, enhanced: request.headers["x-portal-request"] === "navigation"});
  if (url === "/preview/_portal/runtime.js") {
    response.writeHead(200, {"content-type":"text/javascript"}); response.end(runtime); return;
  }
  if (!url.startsWith("/preview/")) { response.writeHead(404); response.end(); return; }
  if (url.startsWith("/preview/logo.png")) { response.writeHead(204); response.end(); return; }
  response.writeHead(200, {"content-type":"text/html", "x-portal-context":"g", "x-portal-version":"v"});
  response.end(source.replace("</body>", '<script type="module" src="/preview/_portal/runtime.js"></script></body>'));
});
await new Promise<void>(resolve => server.listen(0, "127.0.0.1", resolve));
const address = server.address();
if (!address || typeof address === "string") throw new Error("Missing address");
const origin = `http://127.0.0.1:${address.port}`;
const browser = await chromium.launch({headless:true});
try {
  for (const javaScriptEnabled of [false, true]) {
    const context = await browser.newContext({javaScriptEnabled});
    const page = await context.newPage();
    await page.goto(origin + "/preview/orders/123?site=shop&version=draft");
    assert.equal(await page.locator('img[src="/preview/logo.png"]').count(), 1);
    assert.equal(await page.locator('a[href="/preview/api?q=1"]').count(), 1);
    assert.equal(await page.locator('a[data-portal-url-kind="asset"]').getAttribute("href"), "/preview/manual.svg");
    const form = page.locator("form");
    assert.equal(await form.locator('input[name="site"]').inputValue(), "shop");
    assert.equal(await form.locator('input[name="version"]').inputValue(), "draft");
    await form.locator('input[name="q"]').fill("print / book");
    if (javaScriptEnabled) {
      await page.waitForFunction(() => document.documentElement.dataset.portalBase === "/preview");
      await page.evaluate(() => { document.documentElement.dataset.clientMarker = "retained"; });
    }
    await Promise.all([page.waitForURL("**/preview/search?**"), form.locator('input[name="q"]').press("Enter")]);
    const result = new URL(page.url());
    assert.equal(result.pathname, "/preview/search");
    assert.equal(result.searchParams.get("q"), "print / book");
    assert.equal(result.searchParams.get("site"), "shop");
    assert.equal(result.searchParams.get("version"), "draft");
    if (javaScriptEnabled) {
      assert.ok(requests.some(request => request.url.startsWith("/preview/search?") && request.enhanced));
      assert.equal(await page.locator("html").getAttribute("data-client-marker"), "retained");
      await page.locator('a[href="/preview/catalog?site=shop&version=draft"]').click();
      await page.waitForURL("**/preview/catalog?site=shop&version=draft");
      assert.equal(new URL(page.url()).pathname, "/preview/catalog");
      assert.equal(await page.locator("html").getAttribute("data-client-marker"), "retained");
    }
    await context.close();
  }
  assert.ok(!requests.some(request => request.url.startsWith("/search") || request.url.startsWith("/catalog")));
  console.log("Mounted Chromium URLs passed: real SSR attributes, native/enhanced GET selection, navigation, API and asset separation");
} finally {
  await browser.close();
  await new Promise<void>((resolve, reject) => server.close(error => error ? reject(error) : resolve()));
}
